-
         Lock lock = (type.equals(Type.READ)) ? lockEntry.readLock() : lockEntry.writeLock();

         if (wait == -1) {
@@ -133,6 +111,10 @@ public class MemoryLocks {
                 locks.put(resource, lockEntry);
             }
